    suggested = tmp_path / "s.jsonl"
    suggested.write_text(json.dumps(line) + "\n")
    decisions = tmp_path / "d.jsonl"
    decisions.write_text(json.dumps({"game_id": 2023091002, "play_id": 101, "decision": "consider_alternative",
                                     "down": 3, "yards_to_go": 7, "pass_result": "C",
                                     "play_description": "real play"}) + "\n")
    play = PlayStore(str(tmp_path / "none"), str(decisions), str(suggested)).suggested["2023091002_101"]
    assert (play["down"], play["yardsToGo"], play["firstDownLine"], play["passResult"]) == (3, 7, 57.0, "C")
    assert play["realPlayDescription"] == "real play"


