# --- 2025 suggested plays (roster block, real clubs and jerseys) -----------------

# Generated by running decision_engine's 2025 path (suggested_play) on the made-up
# game in packages/counterfactual/tests/test_engine_2025.py: play 100 goes right,
# play 101 goes left and recommends a receiver other than the one targeted.
SUGGESTED_2025 = Path(__file__).parent / "fixtures_suggested_2025.jsonl"


@pytest.fixture
def client_2025(tmp_path, monkeypatch):
    suggested = tmp_path / "suggested_plays.jsonl"
    suggested.write_text(SUGGESTED_2025.read_text())
    monkeypatch.setattr(main, "store", PlayStore(str(tmp_path / "none"), str(tmp_path / "none.jsonl"), str(suggested)))
    return TestClient(main.app)


def test_2025_plays_carry_real_teams_jerseys_and_context(client_2025):
    play = client_2025.get("/plays/2022090800_101/suggested").json()
    assert (play["possessionTeam"], play["defensiveTeam"]) == ("BUF", "LA")
    assert (play["homeTeam"], play["visitorTeam"]) == ("LA", "BUF")
    sides = {(p["club"], p["side"]) for p in play["players"]}
    assert sides == {("BUF", "offense"), ("LA", "defense")}
    assert sum(p["side"] == "offense" for p in play["players"]) == 11
    assert all(p["jerseyNumber"] == p["nflId"] for p in play["players"])  # the fixture's jerseys equal ids
    assert (play["quarter"], play["gameClock"], play["down"], play["yardsToGo"]) == (1, "10:00", 2, 7)
    assert play["realPlayDescription"] == "pass 101"


def test_2025_recommendation_ids_are_integers_unity_can_read(client_2025):
    rec = client_2025.get("/plays/2022090800_101/suggested").json()["recommendation"]
    assert (rec["targetNflId"], rec["targetedNflId"]) == (3, 2)
    assert all(isinstance(v, int) for v in (rec["targetNflId"], rec["targetedNflId"]))
    assert rec["reason"].startswith("The model projects Player 3")
    same = client_2025.get("/plays/2022090800_100/suggested").json()["recommendation"]
    assert same["targetNflId"] == same["targetedNflId"] == 2


def test_2025_forecast_frames_are_labelled_and_the_ball_lands_on_the_receiver(client_2025):
    play = client_2025.get("/plays/2022090800_101/suggested").json()
    sim = play["simulationStartFrameId"]
    assert sim == play["sourceFrameId"] + 1
    before = {p["oSource"] for f in play["frames"] if f["frameId"] < sim for p in f["players"]}
    after = {p["oSource"] for f in play["frames"] if f["frameId"] >= sim for p in f["players"]}
    assert before == {"measured"} and after == {"from_velocity"}
    assert [(f["frameId"], f["event"]) for f in play["frames"] if f["event"]] == [
        (11, "ball_snap"), (25, "pass_forward"), (33, "pass_arrived")]
    last = play["frames"][-1]
    receiver = next(p for p in last["players"] if p["nflId"] == 3)
    assert abs(last["ball"]["x"] - receiver["x"]) < 0.02 and abs(last["ball"]["y"] - receiver["y"]) < 0.02


def test_2025_left_play_is_flipped_so_the_offense_attacks_plus_x(client_2025):
    left = client_2025.get("/plays/2022090800_101/suggested").json()
    right = client_2025.get("/plays/2022090800_100/suggested").json()
    assert left["lineOfScrimmage"] == right["lineOfScrimmage"] == 40.0
    for play in (left, right):
        qb = next(p for f in play["frames"] if f["frameId"] == 25 for p in f["players"] if p["nflId"] == 1)
        assert qb["x"] < play["lineOfScrimmage"]
